package com.talk2;

import android.bluetooth.*;
import android.bluetooth.le.*;
import android.content.Context;
import android.os.Build;
import android.os.ParcelUuid;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

/** Independent BLE/GATT transport. Bounded to three live links; no impact on PeerRadio. */
final class BleMeshTransport {
 interface Listener { void packet(String neighbor,String wire); void peer(String id,boolean up); void error(String message); }
 static final UUID SERVICE=UUID.fromString("8927ac10-12aa-4e42-9aaf-2147d3c88f11"), DATA=UUID.fromString("8927ac11-12aa-4e42-9aaf-2147d3c88f11");
 private static final int MAX_LINKS=MeshRouter.MAX_NEIGHBORS;
 private final Context context;private final Listener listener;private final BluetoothManager manager;private final BluetoothAdapter adapter;private final BluetoothLeScanner scanner;private final BluetoothLeAdvertiser advertiser;private BluetoothGattServer server;private ScanCallback scanCallback;private boolean running;
 private final Map<String,BluetoothGatt> clients=new ConcurrentHashMap<>();private final Map<String,Integer> mtus=new ConcurrentHashMap<>();private final Map<String,MeshSendQueue> writes=new ConcurrentHashMap<>();private final Map<String,TimedAssembly> assemblies=new ConcurrentHashMap<>();private final Map<String,byte[]> inFlight=new ConcurrentHashMap<>();private final Map<String,Integer> retries=new ConcurrentHashMap<>();private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());
 private final Set<String> discoveryStarted=ConcurrentHashMap.newKeySet();private final Map<String,Long> writeGeneration=new ConcurrentHashMap<>();
 private final Map<String,Integer> connectionRefs=new ConcurrentHashMap<>();private final Set<String> registeredClients=ConcurrentHashMap.newKeySet();
 private static final class TimedAssembly {final MeshFragmentCodec.Assembly value;final long started=System.currentTimeMillis();TimedAssembly(MeshFragmentCodec.Frame first){value=new MeshFragmentCodec.Assembly(first);}}
 BleMeshTransport(Context c,Listener l){context=c.getApplicationContext();listener=l;manager=(BluetoothManager)c.getSystemService(Context.BLUETOOTH_SERVICE);adapter=manager==null?null:manager.getAdapter();scanner=adapter==null?null:adapter.getBluetoothLeScanner();advertiser=adapter==null?null:adapter.getBluetoothLeAdvertiser();}
 synchronized void start()throws Exception{if(running)return;if(adapter==null||!adapter.isEnabled()||scanner==null||advertiser==null)throw new IllegalStateException("BLE advertiser and scanner are unavailable");server=manager.openGattServer(context,gattServerCallback);if(server==null)throw new IllegalStateException("Could not open BLE GATT server");BluetoothGattService service=new BluetoothGattService(SERVICE,BluetoothGattService.SERVICE_TYPE_PRIMARY);BluetoothGattCharacteristic characteristic=new BluetoothGattCharacteristic(DATA,BluetoothGattCharacteristic.PROPERTY_WRITE|BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE|BluetoothGattCharacteristic.PROPERTY_NOTIFY,BluetoothGattCharacteristic.PERMISSION_WRITE);characteristic.addDescriptor(new BluetoothGattDescriptor(UUID.fromString("00002902-0000-1000-8000-00805f9b34fb"),BluetoothGattDescriptor.PERMISSION_READ|BluetoothGattDescriptor.PERMISSION_WRITE));service.addCharacteristic(characteristic);if(!server.addService(service))throw new IllegalStateException("Could not register mesh GATT service");AdvertiseSettings settings=new AdvertiseSettings.Builder().setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY).setConnectable(true).setTimeout(0).setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_LOW).build();AdvertiseData data=new AdvertiseData.Builder().addServiceUuid(new ParcelUuid(SERVICE)).setIncludeDeviceName(false).build();advertiser.startAdvertising(settings,data,advertiseCallback);scanCallback=new ScanCallback(){@Override public void onScanResult(int callbackType,ScanResult r){connect(r.getDevice());}@Override public void onScanFailed(int code){listener.error("BLE scan failed: "+code);}};scanner.startScan(Collections.singletonList(new ScanFilter.Builder().setServiceUuid(new ParcelUuid(SERVICE)).build()),new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCallback);running=true;}
 synchronized void stop(){running=false;try{if(scanner!=null&&scanCallback!=null)scanner.stopScan(scanCallback);}catch(Exception ignored){}try{if(advertiser!=null)advertiser.stopAdvertising(advertiseCallback);}catch(Exception ignored){}if(server!=null){server.close();server=null;}for(BluetoothGatt g:clients.values())try{g.disconnect();g.close();}catch(Exception ignored){}clients.clear();mtus.clear();writes.clear();assemblies.clear();inFlight.clear();retries.clear();connectionRefs.clear();registeredClients.clear();discoveryStarted.clear();writeGeneration.clear();handler.removeCallbacksAndMessages(null);}
 private final AdvertiseCallback advertiseCallback=new AdvertiseCallback(){@Override public void onStartFailure(int errorCode){listener.error("BLE advertise failed: "+errorCode);}};
 private synchronized void connect(BluetoothDevice d){String id=d.getAddress();if(!running||clients.containsKey(id)||clients.size()>=MAX_LINKS)return;try{BluetoothGatt g;if(Build.VERSION.SDK_INT>=23)g=d.connectGatt(context,false,gattCallback,BluetoothDevice.TRANSPORT_LE);else g=d.connectGatt(context,false,gattCallback);if(g!=null)clients.put(id,g);}catch(SecurityException e){listener.error("Bluetooth connect permission missing");}}
 private final BluetoothGattServerCallback gattServerCallback=new BluetoothGattServerCallback(){@Override public void onConnectionStateChange(BluetoothDevice d,int status,int state){String id=d.getAddress();if(state==BluetoothProfile.STATE_CONNECTED){if(!connectionRefs.containsKey(id)&&connectionRefs.size()>=MAX_LINKS){server.cancelConnection(d);return;}addConnection(id);}else{removeConnection(id);assemblies.remove(id);}}@Override public void onCharacteristicWriteRequest(BluetoothDevice d,int requestId,BluetoothGattCharacteristic c,boolean prepared,boolean responseNeeded,int offset,byte[] value){if(responseNeeded&&server!=null)server.sendResponse(d,requestId,BluetoothGatt.GATT_SUCCESS,offset,null);acceptChunk(d.getAddress(),value);}};
 private final BluetoothGattCallback gattCallback=new BluetoothGattCallback(){@Override public void onConnectionStateChange(BluetoothGatt g,int status,int state){String id=g.getDevice().getAddress();if(state==BluetoothProfile.STATE_CONNECTED){mtus.put(id,23);if(!g.requestMtu(185))discoverGatt(g);else handler.postDelayed(()->{if(clients.get(id)==g)discoverGatt(g);},2000);}else{if(registeredClients.remove(id))removeConnection(id);clients.remove(id);discoveryStarted.remove(id);mtus.remove(id);writes.remove(id);inFlight.remove(id);try{g.close();}catch(Exception ignored){}}}@Override public void onMtuChanged(BluetoothGatt g,int mtu,int status){if(status==BluetoothGatt.GATT_SUCCESS)mtus.put(g.getDevice().getAddress(),mtu);discoverGatt(g);}@Override public void onServicesDiscovered(BluetoothGatt g,int status){String id=g.getDevice().getAddress();if(status==BluetoothGatt.GATT_SUCCESS&&g.getService(SERVICE)!=null){if(!connectionRefs.containsKey(id)&&connectionRefs.size()>=MAX_LINKS){g.disconnect();g.close();clients.remove(id);return;}if(registeredClients.add(id))addConnection(id);sendNext(g);}else {listener.error("Mesh GATT service negotiation failed");g.disconnect();}}@Override public void onCharacteristicWrite(BluetoothGatt g,BluetoothGattCharacteristic c,int status){String id=g.getDevice().getAddress();if(status==BluetoothGatt.GATT_SUCCESS){MeshSendQueue q=writes.get(id);if(q!=null)q.sent();inFlight.remove(id);retries.remove(id);sendNext(g);}else retryWrite(g);}};
 private void discoverGatt(BluetoothGatt g){if(discoveryStarted.add(g.getDevice().getAddress())&&!g.discoverServices())g.disconnect();}
 private synchronized void addConnection(String id){int count=connectionRefs.getOrDefault(id,0);connectionRefs.put(id,count+1);if(count==0)listener.peer(id,true);}
 private synchronized void removeConnection(String id){int count=connectionRefs.getOrDefault(id,0);if(count<=1){connectionRefs.remove(id);listener.peer(id,false);}else connectionRefs.put(id,count-1);}
 private void acceptChunk(String id,byte[] bytes){try{MeshFragmentCodec.Frame part=MeshFragmentCodec.parse(bytes);TimedAssembly a=assemblies.get(id);if(a==null||part.index==0||System.currentTimeMillis()-a.started>30000){if(assemblies.size()>=MAX_LINKS*2)assemblies.clear();a=new TimedAssembly(part);assemblies.put(id,a);}if(!a.value.add(part))throw new IllegalArgumentException("Conflicting fragment");if(a.value.complete()){assemblies.remove(id);listener.packet(id,new String(a.value.finish(),StandardCharsets.UTF_8));}}catch(Exception e){assemblies.remove(id);listener.error("Invalid BLE mesh fragment");}}
 void send(String id,String wire)throws Exception{byte[] data=wire.getBytes(StandardCharsets.UTF_8);BluetoothGatt g=clients.get(id);if(g==null||!registeredClients.contains(id))throw new IllegalStateException("BLE neighbor is not ready");MeshPacket packet=MeshPacket.parse(wire);MeshSendQueue q=writes.computeIfAbsent(id,k->new MeshSendQueue());if(!q.offer(packet.id(),packet.priority(),MeshFragmentCodec.fragment(data,mtus.getOrDefault(id,23))))throw new IllegalStateException("BLE neighbor queue full; retry later");sendNext(g);}
 private void sendNext(BluetoothGatt g){String id=g.getDevice().getAddress();MeshSendQueue q=writes.get(id);if(q==null||inFlight.containsKey(id))return;synchronized(q){byte[] part=q.peek();if(part==null)return;BluetoothGattCharacteristic c=g.getService(SERVICE)==null?null:g.getService(SERVICE).getCharacteristic(DATA);if(c==null){listener.error("BLE data characteristic unavailable");return;}long generation=writeGeneration.getOrDefault(id,0L)+1;writeGeneration.put(id,generation);inFlight.put(id,part);boolean started;if(Build.VERSION.SDK_INT>=33)started=g.writeCharacteristic(c,part,BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT)==BluetoothStatusCodes.SUCCESS;else{c.setWriteType(BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT);c.setValue(part);started=g.writeCharacteristic(c);}if(started)handler.postDelayed(()->{if(writeGeneration.getOrDefault(id,0L)==generation&&inFlight.containsKey(id))retryWrite(g);},5000);else {inFlight.remove(id);retryWrite(g);}}}
 private void retryWrite(BluetoothGatt g){String id=g.getDevice().getAddress();int attempt=retries.getOrDefault(id,0)+1;retries.put(id,attempt);if(attempt>5){listener.error("BLE send paused after retries; reconnect to continue");g.disconnect();return;}long delay=Math.min(15000,500L<<(attempt-1));handler.postDelayed(()->{inFlight.remove(id);sendNext(g);},delay);}
}
